:root {
  --ink: #17130f;
  --paper: #e7dcc4;
  --paper-dim: #b6a98d;
  --gold: #c9a55e;
  --gold-bright: #ead08a;
  --red: #8f1f1c;
  --green: #3b5d35;
  --hud-font: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --serif: 'Cormorant Garamond', Georgia, serif;
  --display: 'Cinzel', Georgia, serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #17130f;
  color: var(--paper);
  font-family: var(--hud-font);
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

#app, #app canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

#app canvas { cursor: crosshair; }

.hidden { display: none !important; }

#vignette, #grain, #damage-flash, #slowmo {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
}

#vignette {
  background:
    radial-gradient(ellipse at center, transparent 35%, rgba(13, 9, 6, 0.16) 62%, rgba(8, 6, 4, 0.74) 100%),
    linear-gradient(to bottom, rgba(18, 13, 8, 0.2), transparent 20%, transparent 70%, rgba(12, 8, 5, 0.34));
}

#grain {
  opacity: 0.16;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.42'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

#damage-flash {
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 22%, rgba(115, 10, 8, 0.48) 100%);
  transition: opacity 0.12s ease-out;
  z-index: 9;
}

#damage-flash.hit { opacity: 1; }

#slowmo {
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 20%, rgba(68, 5, 4, 0.6) 100%);
  transition: opacity 0.4s;
  z-index: 8;
}
#slowmo.on { opacity: 1; }

/* ---------- HUD ---------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  font-family: var(--hud-font);
  letter-spacing: 0.08em;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  padding: max(18px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.objective-block, .strength-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 205px;
}
.strength-block { text-align: right; align-items: flex-end; }

.eyebrow {
  font-size: 10px;
  color: var(--gold);
  letter-spacing: 0.3em;
  font-weight: 600;
}

.objective {
  font-family: var(--display);
  font-size: clamp(17px, 1.6vw, 24px);
  letter-spacing: 0.13em;
  color: #f1e5cc;
  line-height: 1.1;
}

.sub-objective {
  font-size: 11px;
  color: var(--paper-dim);
  letter-spacing: 0.18em;
}

.strength, .enemy-count {
  font-size: 12px;
  color: var(--paper);
  letter-spacing: 0.16em;
}
.strength b, .enemy-count b {
  font-size: 20px;
  color: var(--gold-bright);
  font-weight: 600;
  margin-right: 4px;
  font-variant-numeric: tabular-nums;
}
.enemy-count { color: #c7b89e; font-size: 10px; }
.enemy-count b { font-size: 14px; color: #d8c19a; }

.compass-wrap {
  position: relative;
  width: min(36vw, 430px);
  height: 44px;
  margin-top: 2px;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(to right, transparent, black 14%, black 86%, transparent);
  mask-image: linear-gradient(to right, transparent, black 14%, black 86%, transparent);
}
.compass {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 25px;
  padding: 0 10%;
  color: rgba(236, 224, 200, 0.66);
  font-size: 11px;
  letter-spacing: 0.22em;
}
.compass span:nth-child(3) { color: var(--gold-bright); font-size: 15px; }
.compass-needle {
  position: absolute;
  left: 50%;
  bottom: 7px;
  width: 1px;
  height: 9px;
  background: var(--gold-bright);
  transform: translateX(-50%);
}
.compass-objective {
  position: absolute;
  bottom: 4px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--red);
  font-size: 11px;
  text-shadow: 0 0 7px rgba(180, 40, 20, 0.8);
  transition: left 0.15s;
}

.hud-bottom {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  right: max(22px, env(safe-area-inset-right));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 250px 1fr 260px;
  align-items: end;
  gap: 20px;
}

.health-block { width: 240px; }
.health-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  font-size: 10px;
  color: var(--gold);
  letter-spacing: 0.26em;
}
.health-head #health-num {
  font-size: 22px;
  color: #f0e1c3;
  letter-spacing: 0.05em;
  font-weight: 500;
}
.health-bar {
  position: relative;
  height: 7px;
  background: rgba(15, 11, 8, 0.65);
  border: 1px solid rgba(221, 201, 165, 0.28);
  margin-top: 5px;
  overflow: hidden;
}
.health-bar i, .health-bar em {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  display: block;
}
.health-bar i {
  width: 100%;
  background: linear-gradient(90deg, #6c1a16, #b0432e 55%, #d7a75e);
  transition: width 0.18s ease-out;
}
.health-bar em {
  width: 100%;
  background: rgba(238, 220, 180, 0.35);
  transition: width 0.8s ease-in 0.25s;
}
.stance {
  margin-top: 7px;
  font-size: 9px;
  letter-spacing: 0.19em;
  color: rgba(214, 200, 174, 0.64);
}

.controls-hint {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 5px 14px;
  padding-bottom: 4px;
  color: rgba(224, 210, 185, 0.5);
  font-size: 9px;
  letter-spacing: 0.16em;
  opacity: 0.8;
  transition: opacity 1.2s;
}
.controls-hint b { color: var(--gold); font-weight: 600; margin-right: 2px; }
.controls-hint.fade { opacity: 0; }

.ammo-block { text-align: right; }
.weapon-name {
  font-size: 9px;
  color: var(--gold);
  letter-spacing: 0.25em;
}
.ammo-line {
  line-height: 0.82;
  margin: 2px 0 4px;
  color: #f2e5c8;
}
.ammo-line #ammo-count { font-size: 52px; font-weight: 300; letter-spacing: 0; font-variant-numeric: tabular-nums; }
.ammo-line .ammo-max { font-size: 15px; color: rgba(231, 216, 186, 0.55); margin-left: 4px; }
.reload-bar {
  height: 2px;
  background: rgba(231, 214, 180, 0.16);
  margin: 5px 0 5px auto;
  width: 155px;
  overflow: hidden;
}
.reload-bar i {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--gold-bright);
  box-shadow: 0 0 7px rgba(234, 208, 138, 0.6);
  transition: width 0.05s linear;
}
.ammo-state { font-size: 9px; color: rgba(229, 213, 183, 0.6); letter-spacing: 0.2em; }

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46px;
  height: 46px;
  transform: translate(-50%, -50%);
  opacity: 0.92;
  --spread: 7px;
  transition: opacity 0.2s;
}
.crosshair i {
  position: absolute;
  background: rgba(244, 233, 211, 0.92);
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.8);
  transition: all 0.1s;
}
.ch-top, .ch-bottom { left: 50%; width: 1px; height: 8px; margin-left: -0.5px; }
.ch-left, .ch-right { top: 50%; width: 8px; height: 1px; margin-top: -0.5px; }
.ch-top { top: calc(50% - var(--spread) - 8px); }
.ch-bottom { top: calc(50% + var(--spread)); }
.ch-left { left: calc(50% - var(--spread) - 8px); }
.ch-right { left: calc(50% + var(--spread)); }
.ch-dot {
  position: absolute;
  left: 50%; top: 50%;
  width: 3px; height: 3px;
  margin: -1.5px 0 0 -1.5px;
  border-radius: 50%;
  background: rgba(247, 235, 211, 0.96);
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.9);
}
.ch-ring {
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(222, 205, 172, 0.14);
  border-radius: 50%;
  opacity: 0;
  transition: opacity 0.2s;
}
.crosshair.aim .ch-ring { opacity: 1; }
.crosshair.aim i { background: rgba(255, 246, 223, 1); }

.hitmarker {
  position: absolute;
  left: 50%; top: 50%;
  width: 30px; height: 30px;
  transform: translate(-50%, -50%) rotate(45deg);
  opacity: 0;
  transition: opacity 0.08s;
}
.hitmarker.show { opacity: 1; }
.hitmarker i {
  position: absolute;
  width: 9px; height: 1px;
  background: #f2e6cd;
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.7);
}
.hitmarker i:nth-child(1) { left: 0; top: 0; transform-origin: left; transform: rotate(45deg); }
.hitmarker i:nth-child(2) { right: 0; top: 0; transform-origin: right; transform: rotate(-45deg); }
.hitmarker i:nth-child(3) { left: 0; bottom: 0; transform-origin: left; transform: rotate(-45deg); }
.hitmarker i:nth-child(4) { right: 0; bottom: 0; transform-origin: right; transform: rotate(45deg); }
.hitmarker.kill i { background: #d55a42; height: 2px; }

.hit-text {
  position: absolute;
  left: 50%;
  top: calc(50% + 34px);
  transform: translateX(-50%);
  color: #f1d49a;
  font-size: 10px;
  letter-spacing: 0.25em;
  opacity: 0;
  transition: opacity 0.15s;
}
.hit-text.show { opacity: 1; }

.killfeed {
  position: absolute;
  right: max(22px, env(safe-area-inset-right));
  top: 100px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
  font-size: 10px;
  letter-spacing: 0.15em;
}
.killfeed div {
  background: linear-gradient(90deg, transparent, rgba(17, 12, 8, 0.56));
  padding: 4px 0 4px 22px;
  color: rgba(230, 215, 188, 0.8);
  animation: feedIn 0.24s ease-out both;
}
.killfeed b { color: var(--gold-bright); font-weight: 600; }
.killfeed .head { color: #d8634c; }
@keyframes feedIn { from { opacity: 0; transform: translateX(12px); } }

.subtitle {
  position: absolute;
  left: 50%;
  bottom: 150px;
  transform: translateX(-50%);
  width: min(650px, 70vw);
  text-align: center;
  font-family: var(--serif);
  font-size: clamp(15px, 1.45vw, 21px);
  font-style: italic;
  letter-spacing: 0.02em;
  color: #eadfc9;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.9);
  opacity: 0;
  transition: opacity 0.35s;
}
.subtitle.show { opacity: 1; }
.subtitle .speaker {
  display: block;
  font-family: var(--hud-font);
  font-style: normal;
  font-size: 9px;
  letter-spacing: 0.3em;
  color: var(--gold);
  margin-bottom: 3px;
}

.order-banner {
  position: absolute;
  left: 50%;
  top: 20%;
  transform: translate(-50%, -8px);
  text-align: center;
  opacity: 0;
  transition: opacity 0.5s, transform 0.5s;
}
.order-banner.show { opacity: 1; transform: translate(-50%, 0); }
.order-banner span {
  display: block;
  font-size: 10px;
  letter-spacing: 0.36em;
  color: var(--gold);
}
.order-banner b {
  display: block;
  font-family: var(--display);
  font-size: clamp(20px, 2.6vw, 38px);
  letter-spacing: 0.14em;
  font-weight: 500;
  color: #f1e2c4;
  text-shadow: 0 3px 18px rgba(0, 0, 0, 0.85);
  margin-top: 4px;
}

.mute {
  position: absolute;
  left: 50%;
  bottom: 92px;
  transform: translateX(-50%);
  font-size: 9px;
  letter-spacing: 0.28em;
  color: var(--paper-dim);
  opacity: 0;
  transition: opacity 0.2s;
}
.mute.show { opacity: 1; }

/* ---------- screens ---------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 62% 45%, rgba(17, 12, 8, 0.08) 0%, rgba(17, 12, 8, 0.72) 75%),
    linear-gradient(90deg, rgba(17, 12, 8, 0.93) 0%, rgba(17, 12, 8, 0.62) 45%, rgba(17, 12, 8, 0.32) 100%);
  backdrop-filter: blur(2px);
}

.start-screen {
  justify-content: flex-start;
  padding: clamp(24px, 5vw, 88px);
}
.start-screen::after {
  content: '';
  position: absolute;
  inset: 20px;
  border: 1px solid rgba(207, 181, 125, 0.22);
  pointer-events: none;
}
.start-inner {
  position: relative;
  z-index: 2;
  width: min(640px, 58vw);
  animation: reveal 1.1s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes reveal { from { opacity: 0; transform: translateY(16px); } }

.title-rule {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--gold);
  font-size: 9px;
  letter-spacing: 0.35em;
  margin-bottom: 14px;
}
.title-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(201,165,94,0.55)); }
.title-rule span:last-child { background: linear-gradient(90deg, rgba(201,165,94,0.55), transparent); }
.title-rule i { font-style: normal; white-space: nowrap; }

.start-inner h1 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(50px, 7.2vw, 108px);
  font-weight: 600;
  line-height: 0.84;
  letter-spacing: 0.03em;
  color: #f2e6ce;
  text-shadow: 0 5px 40px rgba(0, 0, 0, 0.55);
}
.start-inner h1 em {
  font-style: normal;
  font-size: 0.66em;
  letter-spacing: 0.13em;
  color: var(--gold-bright);
}
.start-sub {
  margin-top: 18px;
  color: var(--gold);
  font-size: 12px;
  letter-spacing: 0.42em;
}
.start-sub span { margin: 0 6px; color: rgba(201, 165, 94, 0.55); }
.start-copy {
  max-width: 430px;
  margin: 22px 0 26px;
  font-family: var(--serif);
  font-size: 18px;
  line-height: 1.45;
  color: rgba(226, 213, 190, 0.78);
}

.start-button {
  position: relative;
  appearance: none;
  border: 1px solid rgba(234, 208, 138, 0.7);
  background: linear-gradient(180deg, rgba(132, 91, 37, 0.9), rgba(79, 51, 20, 0.9));
  color: #f5e7c9;
  font-family: var(--hud-font);
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.34em;
  padding: 14px 46px 14px 52px;
  cursor: pointer;
  box-shadow: 0 0 0 4px rgba(17, 12, 8, 0.3), 0 8px 30px rgba(0, 0, 0, 0.3), inset 0 1px rgba(255, 240, 205, 0.2);
  transition: transform 0.16s, background 0.16s, box-shadow 0.16s;
}
.start-button::before, .start-button::after {
  content: '◆';
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(245, 231, 201, 0.6);
  font-size: 8px;
}
.start-button::before { left: 20px; }
.start-button::after { right: 20px; }
.start-button:hover {
  transform: translateY(-1px);
  background: linear-gradient(180deg, rgba(160, 114, 51, 0.95), rgba(95, 63, 27, 0.95));
  box-shadow: 0 0 0 4px rgba(17, 12, 8, 0.3), 0 10px 36px rgba(0, 0, 0, 0.42), 0 0 30px rgba(201, 165, 94, 0.16);
}
.start-button:active { transform: translateY(1px); }
.start-button.small { font-size: 14px; padding: 11px 40px; }

.start-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin-top: 26px;
  color: rgba(212, 198, 173, 0.56);
  font-size: 9px;
  letter-spacing: 0.18em;
}
.start-controls b { color: var(--gold); font-weight: 600; }
.start-foot {
  display: flex;
  justify-content: space-between;
  margin-top: 32px;
  padding-top: 12px;
  border-top: 1px solid rgba(201, 165, 94, 0.18);
  color: rgba(201, 165, 94, 0.5);
  font-size: 8px;
  letter-spacing: 0.3em;
}

.start-side {
  position: absolute;
  right: clamp(24px, 6vw, 110px);
  bottom: clamp(40px, 7vw, 110px);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 32px;
  z-index: 2;
}
.quote {
  max-width: 230px;
  text-align: right;
  font-family: var(--serif);
  font-style: italic;
  font-size: 17px;
  line-height: 1.35;
  color: rgba(231, 216, 190, 0.58);
}
.quote span {
  display: block;
  margin-top: 10px;
  font-family: var(--hud-font);
  font-style: normal;
  font-size: 8px;
  letter-spacing: 0.28em;
  color: var(--gold);
}
.seal {
  width: 76px;
  height: 76px;
  border: 1px solid rgba(201, 165, 94, 0.45);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  color: var(--gold);
}
.seal i { font-family: var(--display); font-style: normal; font-size: 24px; line-height: 1; }
.seal span { font-size: 6px; letter-spacing: 0.3em; }

.pause-screen, .end-screen {
  background: rgba(15, 11, 8, 0.72);
  backdrop-filter: blur(5px);
}
.pause-inner, .end-inner {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 30px;
}
.pause-inner h2, .end-inner h2 {
  font-family: var(--display);
  font-size: clamp(34px, 5vw, 62px);
  font-weight: 500;
  letter-spacing: 0.14em;
  margin: 6px 0 18px;
  color: #f1e3c6;
}
.pause-inner .start-button, .end-inner .start-button { margin-top: 10px; }
.ghost-button {
  appearance: none;
  background: transparent;
  border: 0;
  border-bottom: 1px solid rgba(201, 165, 94, 0.35);
  color: rgba(224, 210, 185, 0.7);
  font-family: var(--hud-font);
  font-size: 11px;
  letter-spacing: 0.25em;
  padding: 10px 6px 4px;
  margin-top: 16px;
  cursor: pointer;
}
.ghost-button:hover { color: var(--gold-bright); }
.pause-tip { margin-top: 24px; font-size: 9px; letter-spacing: 0.24em; color: rgba(224, 210, 185, 0.4); }
.end-copy { max-width: 460px; font-family: var(--serif); font-size: 19px; line-height: 1.4; color: rgba(226, 213, 190, 0.72); margin: 0 0 26px; }
.end-stats { display: flex; gap: 38px; margin-bottom: 30px; }
.end-stats div { display: flex; flex-direction: column; gap: 4px; }
.end-stats b { font-size: 34px; font-weight: 400; color: var(--gold-bright); line-height: 1; }
.end-stats span { font-size: 8px; letter-spacing: 0.24em; color: rgba(224, 210, 185, 0.55); }
.end-screen.victory .end-inner h2 { color: var(--gold-bright); }

.loading-screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  background: #17130f;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  transition: opacity 0.8s;
}
.loading-screen.done { opacity: 0; pointer-events: none; }
.loading-mark {
  width: 74px; height: 74px;
  border: 1px solid rgba(201, 165, 94, 0.55);
  border-radius: 50%;
  display: grid; place-items: center;
  font-family: var(--display);
  color: var(--gold-bright);
  font-size: 25px;
}
.loading-text { font-size: 9px; letter-spacing: 0.34em; color: var(--gold); animation: pulse 1.6s ease-in-out infinite; }
@keyframes pulse { 50% { opacity: 0.4; } }

/* ---------- touch ---------- */

.touch-ui { position: fixed; inset: 0; z-index: 7; pointer-events: none; }
.joystick {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(24px, env(safe-area-inset-bottom));
  width: 124px; height: 124px;
  border-radius: 50%;
  background: rgba(20, 15, 10, 0.24);
  border: 1px solid rgba(225, 207, 173, 0.22);
  pointer-events: auto;
  touch-action: none;
}
.joystick-ring {
  position: absolute; inset: 26px; border: 1px solid rgba(225, 207, 173, 0.15); border-radius: 50%;
}
.joystick-knob {
  position: absolute; left: 50%; top: 50%;
  width: 48px; height: 48px;
  margin: -24px 0 0 -24px;
  border-radius: 50%;
  background: rgba(201, 165, 94, 0.28);
  border: 1px solid rgba(234, 208, 138, 0.55);
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.25);
}
.look-zone { position: absolute; right: 0; top: 20%; width: 55%; height: 55%; pointer-events: auto; touch-action: none; }
.touch-btn {
  position: absolute;
  appearance: none;
  border-radius: 50%;
  border: 1px solid rgba(234, 208, 138, 0.45);
  background: rgba(27, 20, 13, 0.44);
  color: #ead9b6;
  font-family: var(--hud-font);
  font-size: 10px;
  letter-spacing: 0.12em;
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(2px);
}
.touch-btn:active, .touch-btn.active { background: rgba(153, 111, 48, 0.56); }
.touch-btn.fire {
  right: max(22px, env(safe-area-inset-right));
  bottom: max(36px, env(safe-area-inset-bottom));
  width: 86px; height: 86px;
  font-size: 13px;
  border-color: rgba(214, 116, 80, 0.6);
  background: rgba(86, 33, 22, 0.42);
}
.touch-btn.reload {
  right: max(120px, calc(env(safe-area-inset-right) + 120px));
  bottom: max(32px, env(safe-area-inset-bottom));
  width: 60px; height: 60px;
  font-size: 8px;
}
.touch-btn.aim {
  right: max(38px, env(safe-area-inset-right));
  bottom: max(138px, calc(env(safe-area-inset-bottom) + 138px));
  width: 54px; height: 54px;
  font-size: 8px;
}
.touch-btn.crouch {
  right: max(108px, calc(env(safe-area-inset-right) + 108px));
  bottom: max(104px, calc(env(safe-area-inset-bottom) + 104px));
  width: 52px; height: 52px;
  font-size: 7px;
}

/* ---------- responsive ---------- */

@media (max-width: 900px) {
  .hud-bottom { grid-template-columns: 150px 1fr 150px; gap: 10px; }
  .health-block { width: 145px; }
  .controls-hint { display: none; }
  .compass-wrap { width: 30vw; }
  .start-inner { width: min(560px, 78vw); }
  .start-side { display: none; }
  .ammo-line #ammo-count { font-size: 42px; }
}

@media (max-width: 640px) {
  #hud { padding: max(12px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right)) max(12px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left)); }
  .hud-top { gap: 8px; }
  .objective-block, .strength-block { min-width: 0; }
  .eyebrow { font-size: 7px; letter-spacing: 0.2em; }
  .objective { font-size: 13px; letter-spacing: 0.08em; }
  .sub-objective { font-size: 8px; }
  .strength, .enemy-count { font-size: 8px; }
  .strength b { font-size: 15px; }
  .enemy-count { display: none; }
  .compass-wrap { display: none; }
  .hud-bottom {
    grid-template-columns: 1fr 1fr;
    align-items: end;
    bottom: max(150px, calc(env(safe-area-inset-bottom) + 150px));
  }
  .health-block { width: 120px; }
  .health-head { font-size: 8px; }
  .health-head #health-num { font-size: 18px; }
  .stance { font-size: 7px; letter-spacing: 0.1em; }
  .weapon-name { font-size: 7px; }
  .ammo-line #ammo-count { font-size: 36px; }
  .reload-bar { width: 110px; }
  .ammo-state { font-size: 7px; }
  .subtitle { bottom: 250px; width: 78vw; font-size: 15px; }
  .killfeed { top: 66px; right: 12px; font-size: 8px; }
  .order-banner { top: 16%; }
  .start-screen { padding: 24px 20px; align-items: flex-end; justify-content: center; }
  .start-screen::after { inset: 10px; }
  .start-inner { width: 100%; text-align: center; }
  .title-rule { justify-content: center; }
  .title-rule span { max-width: 50px; }
  .start-inner h1 { font-size: 44px; }
  .start-sub { font-size: 9px; letter-spacing: 0.28em; }
  .start-copy { margin: 16px auto 20px; font-size: 15px; max-width: 340px; }
  .start-button { font-size: 14px; padding: 12px 38px 12px 44px; }
  .start-controls { justify-content: center; gap: 6px 12px; font-size: 8px; margin-top: 20px; }
  .start-foot { display: none; }
  .start-side { display: none; }
  .end-stats { gap: 24px; }
  .end-stats b { font-size: 28px; }
  .pause-inner h2, .end-inner h2 { font-size: 36px; }
}

@media (orientation: landscape) and (max-height: 520px) {
  .hud-bottom { bottom: max(8px, env(safe-area-inset-bottom)); }
  .health-block { width: 120px; }
  .ammo-line #ammo-count { font-size: 32px; }
  .subtitle { bottom: 78px; }
  .killfeed { top: 54px; }
  .start-inner h1 { font-size: 40px; }
  .start-copy { margin: 10px 0 14px; font-size: 14px; }
  .start-controls { margin-top: 12px; }
}

